import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"命令行选项","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"zh/qgc-dev-guide/command_line_options.md","filePath":"zh/qgc-dev-guide/command_line_options.md"}`),a={name:`zh/qgc-dev-guide/command_line_options.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="命令行选项" tabindex="-1">命令行选项 <a class="header-anchor" href="#命令行选项" aria-label="Permalink to “命令行选项”">​</a></h1><p>您可以使用命令行选项启动QGroundControl。 这些用于启用日志记录，运行单元测试以及模拟不同的主机环境以进行测试。 These are used to enable logging, run unit tests, and simulate different host environments for testing.</p><h2 id="使用选项启动qgroundcontrol" tabindex="-1">使用选项启动QGroundControl <a class="header-anchor" href="#使用选项启动qgroundcontrol" aria-label="Permalink to “使用选项启动QGroundControl”">​</a></h2><p>You will need to open a command prompt or terminal, change directory to where the <em>QGroundControl</em> executable is stored, and then run it. This is shown below for each platform (using the <code>--logging:full --log-output</code> options):</p><p>Windows Command Prompt (<em>QGroundControl</em> is a GUI application with no console window, so redirect stderr to a file to capture the output):</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%ProgramFiles%\\QGroundControl\\bin&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">QGroundControl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%USERPROFILE%\\qgc_log.txt&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div><p>macOS Terminal app (<strong>Applications/Utilities</strong>):</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/QGroundControl.app/Contents/MacOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./QGroundControl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span></span></code></pre></div><p>Linux终端：</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./QGroundControl-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;arch&gt;.AppImage </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span></span></code></pre></div><p>Options take their value either after a colon (<code>--logging:full</code>) or as the next argument (<code>--logging full</code>). Run with <code>--help</code> to list the options available in your build.</p><h2 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to “选项”">​</a></h2><p>选项/命令行参数列在下表中。</p><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead><tbody><tr><td><code>--help</code>, <code>--version</code></td><td>Prints the available options or the version, then exits.</td></tr><tr><td><code>--clear-settings</code></td><td>Clears the app settings (reverts <em>QGroundControl</em> back to default settings).</td></tr><tr><td><code>--clear-cache</code></td><td>Clears the cached parameter and airframe data.</td></tr><tr><td><code>--logging:full</code></td><td>Turns on full logging. See <a href="./../qgc-user-guide/troubleshooting/console_logging.html#logging-from-the-command-line">Console Logging</a>.</td></tr><tr><td><code>--logging:Comms.LinkManager,FactSystem.ParameterManager</code></td><td>Turns on the specified comma separated logging categories. A category prefix such as <code>Comms</code> also turns on its sub-categories.</td></tr><tr><td><code>--log-output</code></td><td>Writes log messages to stderr (the terminal on macOS/Linux).</td></tr><tr><td><code>--system-id:id</code></td><td>Sets the MAVLink system ID used by <em>QGroundControl</em>.</td></tr><tr><td><code>--simple-boot-test</code></td><td>Initializes the application subsystems and exits (a quick startup check).</td></tr><tr><td><code>--fake-mobile</code></td><td>(Desktop only) Simulates running on a mobile device.</td></tr><tr><td><code>--allow-multiple</code></td><td>(Desktop only) Allows more than one instance of <em>QGroundControl</em> to run at a time.</td></tr><tr><td><code>--swrast</code></td><td>(Windows and macOS only) Forces software rendering.</td></tr><tr><td><code>--no-windows-assert-ui</code></td><td>(Windows only) Disables the assert dialog boxes.</td></tr></tbody></table><h3 id="unit-test-options" tabindex="-1">Unit Test Options <a class="header-anchor" href="#unit-test-options" aria-label="Permalink to “Unit Test Options”">​</a></h3><p>These options are only available in builds with unit tests (<code>QGC_BUILD_TESTING</code>, on by default in Debug builds). See <a href="./contribute/unit_tests.html">Unit Tests</a>.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--unittest:name</code></td><td>Runs the specified unit test. Leave off <code>:name</code> to run all tests.</td></tr><tr><td><code>--unittest-stress:count</code></td><td>Repeats unit tests <code>count</code> times (<code>count &gt; 0</code>). Combine with <code>--unittest:name</code> to select a test.</td></tr><tr><td><code>--unittest-output:file</code></td><td>Writes the results to <code>file</code> in JUnit XML format.</td></tr><tr><td><code>--unittest-shard:index/count</code></td><td>Runs every <code>count</code>-th test function of a single test, starting at <code>index</code> (1-based).</td></tr><tr><td><code>--label:labels</code></td><td>Selects tests by comma separated labels, for example <code>--label:Unit,Vehicle</code>.</td></tr><tr><td><code>--list-tests</code></td><td>Lists the registered tests (combine with <code>--label</code> to filter) and exits.</td></tr><tr><td><code>--onscreen</code></td><td>Shows test windows on screen instead of running offscreen.</td></tr></tbody></table><p>笔记：</p><ul><li>For example, <code>--unittest:ParameterManagerTest --unittest-stress:20</code> runs <code>ParameterManagerTest</code> 20 times.</li><li>When running unit tests, <em>QGroundControl</em> runs under the control of the unit test (it does not start normally).</li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};